<script setup>
import { Head, router } from '@inertiajs/vue3';
import { reactive, ref } from 'vue';
import AppLayout from '@/Layouts/AppLayout.vue';
import AppNotice from '@/Components/Product/AppNotice.vue';
import '../../../css/marketplace.css';
const props = defineProps({businessLabel:String,report:Object,filters:Object,locations:Array,currencies:Object,searchConsole:Object});
const filters = reactive({...props.filters}), busy = ref(false);
const refresh = () => {if(busy.value)return;busy.value=true;router.get(window.location.pathname, filters, {preserveState:true,preserveScroll:true,onFinish:()=>busy.value=false});};
const money = n => new Intl.NumberFormat(undefined,{style:'currency',currency:props.report.currency}).format(Number(n || 0)/100);
const source = value => ({marketplace_discovery:'Marketplace discovery',external_search:'Search to a public page',owner_link:'Owner-shared link',unknown:'Unknown',direct:'Direct visit'}[value] || 'Unknown');
</script>
<template><AppLayout title="Discovery & booking outcomes" :business-label="businessLabel"><Head title="Discovery & booking outcomes" /><main class="mp-container growth-report"><h1 class="mp-title">Discovery & booking outcomes</h1><p class="mp-lead">Attributed bookings and recorded collections. These figures do not prove additional revenue caused by Marketplace.</p><form class="growth-filters" @submit.prevent="refresh"><label>Location<select v-model="filters.location"><option v-for="l in locations" :value="l.public_id" :key="l.public_id">{{ l.name }}</option></select></label><label>Confirmed from<input type="date" v-model="filters.start_date" required /></label><label>Through<input type="date" v-model="filters.end_date" required /></label><label>Recorded currency<select v-model="filters.currency_code"><option v-for="(label,key) in currencies" :key="key" :value="key">{{ label }}</option></select></label><button type="submit" class="mp-button" :disabled="busy">{{ busy ? 'Loading outcomes…' : 'Show outcomes' }}</button></form><AppNotice v-if="Object.keys($page.props.errors || {}).length" title="Review the report dates" description="Choose valid dates and a location you can access. Your choices are kept." /><p class="mp-muted">{{ report.from }}–{{ report.to }} · {{ report.time_zone }} · {{ report.currency }}. One logical booking is counted once after rescheduling. Outcomes and linked collections reflect the latest saved facts, including later refunds. Appointment value is separate from money received.</p><div class="growth-rows"><article class="mp-card" v-for="(row,i) in report.rows" :key="i"><h2>{{ source(row.source) }}</h2><p class="mp-muted">Last known source: {{ source(row.last_source) }} · Entered through {{ row.entry === 'marketplace_profile' ? 'a Marketplace profile' : row.entry === 'owner_booking_link' ? 'the business booking link' : 'an unknown route' }}{{ row.owner_source !== 'unknown' ? ` · Shared-link label: ${row.owner_source.replaceAll('_',' ')}` : '' }}.</p><dl><div><dt>Confirmed bookings</dt><dd>{{ row.confirmations }}</dd></div><div><dt>Completed visits</dt><dd>{{ row.completed_visits }}</dd></div><div><dt>Cancellations</dt><dd>{{ row.cancellations }}</dd></div><div><dt>No-shows</dt><dd>{{ row.no_shows }}</dd></div><div><dt>New-to-your-business clients</dt><dd>{{ row.new_to_business_clients }}</dd></div><div><dt>Latest appointment value</dt><dd>{{ money(row.booked_minor) }}</dd></div><div><dt>Recorded collections</dt><dd>{{ money(row.collected_minor) }}</dd></div><div><dt>Recorded refunds & voids</dt><dd>{{ money(row.refunded_minor) }}</dd></div><div><dt>Payment allocation changes</dt><dd>{{ money(row.allocation_in_minor - row.allocation_out_minor) }}</dd></div><div><dt>Net recorded collections</dt><dd>{{ money(row.net_recorded_minor) }}</dd></div></dl><p class="mp-muted">{{ row.confidence === 'unknown' ? 'No retained acquisition evidence. The booking entry alone does not identify discovery.' : 'Based on a consented source observation. Shared-link labels are unverified and do not prove causality.' }}</p></article></div><AppNotice v-if="!report.rows.length" title="No confirmed bookings in this range" description="Choose another date range or location. Unknown sources are shown honestly when bookings have no retained discovery evidence." /><p class="mp-muted">Across your business, {{ report.unconfirmed_expired_sessions }} unconfirmed booking sessions started in this range and have expired. Sessions are not unique customers. New clients are distinct clients completing their first recorded visit to your business; no cross-business history is used.</p><section class="mp-card"><h2>Search visibility</h2><p v-if="!searchConsole.available">No Search Console data has been imported for this profile and date range.</p><p v-else>{{ searchConsole.impressions ?? 'Limited' }} impressions · {{ searchConsole.clicks ?? 'Limited' }} clicks. Last imported {{ searchConsole.imported_at }} UTC. Counts below three are withheld.</p><p class="mp-muted">Search Console covers your whole public business profile across locations. It is aggregate search data. It cannot tell us an individual customer’s search phrase or prove a booking came from a particular query.</p></section></main></AppLayout></template>
<style scoped>.growth-report{padding-top:32px;padding-bottom:60px}.growth-report>p{margin:20px 0}.growth-report .mp-title{font-size:36px}.growth-filters{display:flex;flex-wrap:wrap;align-items:end;gap:14px;margin:28px 0}.growth-filters label{display:grid;gap:8px;font-size:14px;min-width:160px}.growth-filters input,.growth-filters select{min-height:44px;border:1px solid var(--border-subtle);border-radius:8px;max-width:100%}.growth-rows{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.growth-rows h2{font-size:24px}.growth-rows dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin:24px 0}.growth-rows dt{font-size:13px;color:var(--text-muted)}.growth-rows dd{font-size:23px;font-weight:650}.growth-rows .mp-muted{overflow-wrap:anywhere}@media(max-width:700px){.growth-rows{grid-template-columns:1fr}.growth-filters label{flex:1;min-width:140px}.growth-report .mp-title{font-size:30px}}</style>
